<?php
namespace App\Livewire\Imports;
use App\Models\ImportBatch; use App\Services\EmployeeImportService; use App\Services\PayrollAdjustmentImportService; use App\Services\SpreadsheetReader; use Livewire\Component; use Livewire\WithFileUploads;
class Center extends Component { use WithFileUploads; public string $kind='employees'; public $file; public function import(SpreadsheetReader $reader,EmployeeImportService $employees,PayrollAdjustmentImportService $adjustments):void{$this->authorize('manage-hr');$this->validate(['kind'=>'required|in:employees,payroll_adjustments','file'=>'required|file|max:10240']);$name=$this->file->getClientOriginalName();$ext=strtolower(pathinfo($name,PATHINFO_EXTENSION));$rows=$reader->read($this->file->getRealPath(),$ext);$batch=$this->kind==='employees'?$employees->import($rows,$name,auth()->id()):$adjustments->import($rows,$name,auth()->id());session()->flash('success',"Import {$batch->status}: {$batch->succeeded_rows} succeeded, {$batch->failed_rows} failed.");$this->reset('file');} public function render(){return view('livewire.imports.center',['batches'=>ImportBatch::latest()->limit(20)->get()]);} }
